CREATE OR REPLACE PROCEDURE sp(para_activity_name text, para_actid integer, para_LName text, para_Fname text) LANGUAGE plpgsql AS $$ DECLARE
  ref_cursor1 CURSOR FOR SELECT * FROM "Participates_in" WHERE "actid" = para_actid FOR UPDATE;
  ref_cursor2 CURSOR FOR SELECT * FROM "Student" FOR UPDATE;
  rec1 RECORD;
  rec2 RECORD;
BEGIN
  UPDATE "Activity" SET "activity_name" = para_activity_name;
  UPDATE "Faculty"
    SET "Rank" = 'Professor'
    WHERE "FacID" IN (SELECT "FacID" FROM "Faculty_Participates_in" WHERE "actid" = para_actid);
  DELETE FROM "Faculty_Participates_in" WHERE "actid" = para_actid;
  OPEN ref_cursor1;
  LOOP
    FETCH ref_cursor1 INTO rec1;
    EXIT WHEN NOT FOUND;
    DELETE FROM "Participates_in" WHERE CURRENT OF ref_cursor1;
  END LOOP;
  CLOSE ref_cursor1;
  OPEN ref_cursor2;
  LOOP
    FETCH ref_cursor2 INTO rec2;
    EXIT WHEN NOT FOUND;
    UPDATE "Student" SET "LName" = para_LName, "Fname" = para_FName WHERE CURRENT OF ref_cursor2;
  END LOOP;
  CLOSE ref_cursor2;
END; $$;
CALL sp('NewName', 790, 'SmithNew', 'JaneNew');

